187	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
188	    @Override
189	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
190	        List<String> missingFields = new ArrayList<>();
191	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
192	            missingFields.add("firstName");
193	        }
194	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
195	            missingFields.add("lastName");
196	        }
197	        // Normalize each supplied address form up front. The structured fields are preferred when
198	        // present; the flat 'address' input remains accepted for backward compatibility. An owner is
199	        // valid when it supplies an address in EITHER form (a non-blank addressLine1, or the flat
200	        // address). A whitespace-only value collapses to the empty string and counts as absent.
201	        String normalizedAddressLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
202	        String normalizedAddressLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
203	        String normalizedFlatAddress = normalizeAddress(ownerFieldsDto.getAddress());
204	        boolean hasStructuredAddress = StringUtils.hasText(normalizedAddressLine1);
205	        boolean hasFlatAddress = StringUtils.hasText(normalizedFlatAddress);
206	        if (!hasStructuredAddress && !hasFlatAddress) {
207	            missingFields.add("address");
208	        }
209	        // Compose the stored/returned address: the structured lines when present (addressLine1, with a
210	        // single space and addressLine2 appended when addressLine2 is present), otherwise the flat form.
211	        String composedAddress;
212	        if (hasStructuredAddress) {
213	            composedAddress = StringUtils.hasText(normalizedAddressLine2)
214	                ? normalizedAddressLine1 + " " + normalizedAddressLine2
215	                : normalizedAddressLine1;
216	        } else {
217	            composedAddress = normalizedFlatAddress;
218	        }
219	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
220	            missingFields.add("city");
221	        }
222	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
223	            missingFields.add("telephone");
224	        }
225	        if (!missingFields.isEmpty()) {
226	            throw new InvalidRequestException(missingFields);
227	        }
228	        HttpHeaders headers = new HttpHeaders();
229	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
230	        // Store (and later return) the normalized structured lines and the composed address. The
231	        // structured lines are kept only when the structured form was supplied; otherwise they are
232	        // cleared so the response reflects the flat form that was actually used.
233	        owner.setAddressLine1(hasStructuredAddress ? normalizedAddressLine1 : null);
234	        owner.setAddressLine2(hasStructuredAddress && StringUtils.hasText(normalizedAddressLine2)
235	            ? normalizedAddressLine2 : null);
236	        owner.setAddress(composedAddress);
237	        // Normalize the telephone into E.164 form (reject with 400 when it cannot form a valid one).
238	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
239	        owner.setTelephone(normalizedTelephone);
240	        // Normalize the (optional) email: reject a syntactically invalid address, otherwise store it lower-cased.
241	        owner.setEmail(normalizeEmail(owner.getEmail()));
242	        // Validate the (optional) postcode: reject with 400 when present but malformed or out of range
243	        // for the city's region. The value (mapped straight from the request) is stored and returned as given.
244	        validatePostcode(owner.getCity(), owner.getPostcode());
245	        // Reject a supplied registration date that lies in the future (later than the server's current
246	        // date) with a 400 Bad Request. Checked against the raw supplied value, before defaulting below.
247	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(LocalDate.now())) {
248	            throw new InvalidRequestException(List.of("registrationDate"));
249	        }
250	        // Default the (optional) registration date to the server's current date when none was supplied.
251	        if (owner.getRegistrationDate() == null) {
252	            owner.setRegistrationDate(LocalDate.now());
253	        }
254	        // The effective registration date must fall on a business day: when it lands on a Saturday or
255	        // Sunday (whether supplied or defaulted above), roll it forward to the next Monday. Every value
256	        // derived from the registration date below (daily create-limit, membership number) uses this
257	        // adjusted date.
258	        owner.setRegistrationDate(rollToBusinessDay(owner.getRegistrationDate()));
259	        // Reject the request once the maximum number of owners for the owner's registration day has
260	        // been reached (100 or more owners already created on that date).
261	        int ownersRegisteredToday = countOwnersRegisteredOn(owner.getRegistrationDate());
262	        if (ownersRegisteredToday >= MAX_OWNERS_PER_DAY) {
263	            throw new DailyOwnerLimitException(owner.getRegistrationDate());
264	        }
265	        // Flag a bulk-signup warning when more than 80 owners had already been created on this
266	        // owner's registration day at the moment this owner was created; otherwise clear it.
267	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
268	        // Reject the request when the owner's city has already reached its owner capacity.
269	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
270	            throw new CityCapacityException(owner.getCity());
271	        }
272	        // The household is keyed deterministically on (normalizedLastName, postcode): the householdId
273	        // is the first 12 hex characters of the SHA-256 digest of '<normalizedLastName>|<postcode>',
274	        // so any two owners with the same last name and postcode automatically resolve to the same
275	        // household without an explicit opt-in. It is assigned up front so it feeds duplicate
276	        // detection (the identity key below), the household-size read-back and household-duplicate
277	        // detection alike.
278	        String householdId = generateHouseholdId(owner.getLastName(), owner.getPostcode());
279	        owner.setHouseholdId(householdId);
280	        // Household-duplicate detection: because the household is keyed on (lastName, postcode), any
281	        // existing owner already carrying this householdId is a member of the same household, so this
282	        // create is a household duplicate. Reject it with 409 unless the caller opts in via
283	        // 'sharesHousehold', which now only bypasses this block (the household link already exists by
284	        // construction) and marks the owner as a declared household member.
285	        boolean householdMemberExists = this.clinicService.findAllOwners().stream()
286	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
287	        boolean declaredHouseholdMember = false;
288	        if (householdMemberExists) {
289	            if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
290	                declaredHouseholdMember = true;
291	            } else {
292	                throw new DuplicateHouseholdException(owner.getLastName(), owner.getPostcode());
293	            }
294	        }
295	        // All duplicate detection is consolidated into this single derived identity key
296	        // ('<normalizedTelephone>|<email or empty>|<householdId or empty>'): reject with 409 only
297	        // when the new owner's WHOLE identity key exactly matches an existing owner's. Because the
298	        // telephone is part of the key, two members of the same household with different telephones
299	        // have different keys and are both allowed; only an exact full-key match is a duplicate.
300	        String identityKey = owner.getIdentityKey();
301	        boolean identityCollision = this.clinicService.findAllOwners().stream()
302	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
303	        if (identityCollision) {
304	            throw new DuplicateIdentityException(identityKey);
305	        }
306	        // Soft-match detection: the new owner is not a hard (identity-key) duplicate, but it may
307	        // still be a likely duplicate of an existing owner. Flag it when an existing owner shares
308	        // this owner's last name (compared case-insensitively with collapsed whitespace) and
309	        // postcode while carrying a DIFFERENT normalized telephone. When several existing owners
310	        // match, the one with the lowest id is chosen so the result is deterministic. A declared
311	        // household member is an intentional co-resident, not a suspected duplicate, so it is never
312	        // flagged (a create that reaches this point sharing a last name and postcode with an
313	        // existing owner is precisely a declared household member).
314	        Owner softMatch = declaredHouseholdMember ? null : findPossibleDuplicate(owner);
315	        if (softMatch != null) {
316	            owner.setPossibleDuplicate(true);
317	            owner.setPossibleDuplicateOf(softMatch.getId());
318	        } else {
319	            owner.setPossibleDuplicate(false);
320	        }
321	        // Record how many existing owners already share this first name and last name
322	        // (compared case-insensitively) before this owner is created.
323	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
324	        // Assign the customer code '<REGION>-<HASH8>' before persisting.
325	        owner.setCustomerCode(generateCustomerCode(owner));
326	        // Assign the membership number '<customerCode>-M<YY>' where YY is the last two
327	        // digits of the registration date year (e.g. 'NSW-1A2B3C4D-M26').
328	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
329	        this.clinicService.saveOwner(owner);
330	        populateHouseholdSize(owner);
331	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
332	        // Emit an audit line carrying the new owner's id, customer code, registration date,
333	        // numeric membership level and membership number.
334	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
335	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
336	            ownerDto.getMembershipLevel(), owner.getMembershipNumber());
337	        headers.setLocation(UriComponentsBuilder.newInstance()
338	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
339	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
340	    }
