378	    /**
379	     * Generate a customer code formatted {@code <REGION>-<HASH8>}, where {@code REGION} is the region
380	     * code derived from the owner's identity (postcode range first, then the city-to-region table,
381	     * otherwise {@code UNKNOWN}) and {@code HASH8} is the first eight upper-case hex characters of the
382	     * SHA-256 digest of {@code normalizedTelephone + lastName} (e.g. {@code NSW-1A2B3C4D}). There is no
383	     * longer any per-city sequence number.
384	     *
385	     * @param owner the owner whose (already-normalized) telephone, last name, postcode and city are read
386	     * @return the generated (collision-free) customer code
387	     */
388	    private String generateCustomerCode(Owner owner) {
389	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
390	        String hash8 = shortSha256Hex(owner.getTelephone() + owner.getLastName(), 8);
391	        String baseCode = region + "-" + hash8;
392	        return deduplicateCustomerCode(baseCode);
393	    }
394	
395	    /**
396	     * Return a customer code that does not collide with any existing owner's customer code. When the
397	     * given base code is already unique it is returned unchanged; otherwise {@code -<n>} is appended
398	     * with the smallest {@code n} of 2 or more that makes the result unique (e.g. {@code NSW-1A2B3C4D},
399	     * then {@code NSW-1A2B3C4D-2}, {@code NSW-1A2B3C4D-3}, ...). The incoming owner is not yet
400	     * persisted, so it never counts as a collision with itself.
401	     *
402	     * @param baseCode the computed {@code <REGION>-<HASH8>} customer code
403	     * @return the de-duplicated customer code
404	     */
405	    private String deduplicateCustomerCode(String baseCode) {
406	        java.util.Set<String> existingCodes = this.clinicService.findAllOwners().stream()
407	            .map(Owner::getCustomerCode)
408	            .filter(java.util.Objects::nonNull)
409	            .collect(java.util.stream.Collectors.toSet());
410	        if (!existingCodes.contains(baseCode)) {
411	            return baseCode;
412	        }
413	        int n = 2;
414	        String candidate = baseCode + "-" + n;
415	        while (existingCodes.contains(candidate)) {
416	            n++;
417	            candidate = baseCode + "-" + n;
418	        }
419	        return candidate;
420	    }
421	
422	    /**
423	     * Derive the region code for an owner's identity. The postcode is preferred: when present and it
424	     * falls within a known region's inclusive 4-digit range (NSW 2000-2099, VIC 3000-3099,
425	     * QLD 4000-4099) that region is returned. Otherwise fall back to the pinned city-to-region table
426	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD), and finally {@code UNKNOWN} for a city with no
427	     * known region.
428	     *
429	     * @param postcode the owner's postcode, may be {@code null}
430	     * @param city     the owner's city
431	     * @return the derived region code
432	     */
433	    private String deriveRegion(String postcode, String city) {
434	        if (postcode != null && POSTCODE_PATTERN.matcher(postcode).matches()) {
435	            int value = Integer.parseInt(postcode);
436	            for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
437	                int[] range = entry.getValue();
438	                if (value >= range[0] && value <= range[1]) {
439	                    return entry.getKey();
440	                }
441	            }
442	        }
443	        String region = CITY_REGION.get(city);
444	        return region != null ? region : "UNKNOWN";
445	    }
446	
447	    /**
448	     * Return the first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
449	     * bytes of {@code input}.
450	     *
451	     * @param input  the value to digest
452	     * @param length the number of leading hex characters to return
453	     * @return the truncated upper-case hex digest
454	     */
455	    private String shortSha256Hex(String input, int length) {
456	        try {
457	            byte[] digest = MessageDigest.getInstance("SHA-256")
458	                .digest(input.getBytes(StandardCharsets.UTF_8));
459	            StringBuilder sb = new StringBuilder(digest.length * 2);
460	            for (byte b : digest) {
461	                sb.append(String.format("%02x", b));
462	            }
463	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
464	        } catch (java.security.NoSuchAlgorithmException e) {
465	            throw new IllegalStateException("SHA-256 not available", e);
466	        }
467	    }
