488	    /**
489	     * Generate a membership number formatted {@code <customerCode>-M<YY>}, where {@code YY} is the
490	     * last two digits of the {@code registrationDate} year (e.g. {@code SYD-SMI-0007-M26}).
491	     *
492	     * @param customerCode     the owner's already-assigned customer code
493	     * @param registrationDate the owner's registration date
494	     * @return the generated membership number
495	     */
496	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
497	        String yy = String.format("%02d", registrationDate.getYear() % 100);
498	        return String.format("%s-M%s", customerCode, yy);
499	    }
