519	    /**
520	     * Count the existing owners whose city matches the given city, comparing case-insensitively with
521	     * collapsed whitespace. The incoming owner is not yet persisted, so it is not included in the count.
522	     *
523	     * @param city the incoming owner's city
524	     * @return the number of existing owners already in that city
525	     */
526	    private int countOwnersInCity(String city) {
527	        String normalizedCity = normalizeForComparison(city);
528	        return (int) this.clinicService.findAllOwners().stream()
529	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
530	            .count();
531	    }
532	
533	    /**
534	     * Count the existing owners whose registration date equals the given date. The incoming owner is
535	     * not yet persisted, so it is not included in the count.
536	     *
537	     * @param registrationDate the incoming owner's registration date
538	     * @return the number of existing owners already registered on that date
539	     */
540	    private int countOwnersRegisteredOn(LocalDate registrationDate) {
541	        return (int) this.clinicService.findAllOwners().stream()
542	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
543	            .count();
544	    }
545	
546	    /**
547	     * Find the existing owner the given (not-yet-persisted) owner is a soft duplicate of: one that
548	     * shares the owner's last name (compared case-insensitively with collapsed whitespace) and
549	     * postcode while carrying a different normalized telephone. A blank postcode never soft-matches
550	     * (postcode is required for the match). When several owners match, the one with the lowest id is
551	     * returned so the result is deterministic; {@code null} when there is no soft match.
552	     *
553	     * @param owner the incoming owner (with normalized telephone and last name resolved)
554	     * @return the lowest-id matching existing owner, or {@code null} when none matches
555	     */
556	    private Owner findPossibleDuplicate(Owner owner) {
557	        if (!StringUtils.hasText(owner.getPostcode())) {
558	            return null;
559	        }
560	        String normalizedLastName = normalizeForComparison(owner.getLastName());
561	        String telephone = owner.getTelephone();
562	        return this.clinicService.findAllOwners().stream()
563	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
564	                && owner.getPostcode().equals(existing.getPostcode())
565	                && !java.util.Objects.equals(telephone, existing.getTelephone()))
566	            .min(java.util.Comparator.comparing(Owner::getId))
567	            .orElse(null);
568	    }
569	
570	    /**
571	     * Generate the deterministic household identifier for the given last name and postcode. The value
572	     * is derived from the normalized (case-insensitive, whitespace-collapsed) last name and the
573	     * postcode, so every owner with the same last name and postcode resolves to the same identifier
574	     * automatically. It is the first 12 upper-case hex characters of the SHA-256 digest of
575	     * {@code <normalizedLastName>|<postcode>} (an absent postcode contributes the empty string).
576	     *
577	     * @param lastName the owner's last name
578	     * @param postcode the owner's postcode, may be {@code null}
579	     * @return the deterministic household identifier
580	     */
581	    private String generateHouseholdId(String lastName, String postcode) {
582	        String key = normalizeForComparison(lastName) + "|" + (postcode == null ? "" : postcode);
583	        return shortSha256Hex(key, 12);
584	    }
585	
586	    /**
587	     * Normalize an owner address for storage: trim and collapse every internal run of whitespace to a
588	     * single space, upper-case the result and expand common street-type abbreviations token by token
589	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value normalizes
590	     * to the empty string. The result is the canonical form that is stored, returned and used for every
591	     * address comparison (household duplicate detection and the shared household id).
592	     *
593	     * @param address the raw address, may be {@code null}
594	     * @return the normalized address
595	     */
596	    private String normalizeAddress(String address) {
597	        if (address == null) {
598	            return "";
599	        }
600	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
601	        if (collapsed.isEmpty()) {
602	            return "";
603	        }
604	        String[] tokens = collapsed.split(" ");
605	        StringBuilder sb = new StringBuilder(collapsed.length());
606	        for (int i = 0; i < tokens.length; i++) {
607	            if (i > 0) {
608	                sb.append(' ');
609	            }
610	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
611	        }
612	        return sb.toString();
613	    }
614	
615	    /**
616	     * Normalize a value for identity comparison: trim, collapse every internal run of whitespace to a
617	     * single space and lower-case the result. A {@code null} value normalizes to the empty string.
618	     *
619	     * @param value the raw value, may be {@code null}
620	     * @return the normalized value
621	     */
622	    private String normalizeForComparison(String value) {
623	        if (value == null) {
624	            return "";
625	        }
626	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
627	    }
628	
629	    /**
630	     * Normalize an optional owner email address. A blank/absent value is treated as "not provided"
631	     * and returns {@code null}. When present, the value must be a syntactically valid address; if it
632	     * is not, an {@link InvalidRequestException} is thrown (mapped to 400 Bad Request). A valid value
633	     * is returned lower-cased.
634	     *
635	     * @param email the raw email from the request payload, may be {@code null}
636	     * @return the lower-cased email, or {@code null} when none was provided
637	     */
638	    private String normalizeEmail(String email) {
639	        if (!StringUtils.hasText(email)) {
640	            return null;
641	        }
642	        if (!EMAIL_PATTERN.matcher(email).matches()) {
643	            throw new InvalidRequestException(List.of("email"));
644	        }
645	        String lowerCased = email.toLowerCase(Locale.ROOT);
646	        // Reject an address whose domain is on the disposable-domain blocklist.
647	        String domain = lowerCased.substring(lowerCased.indexOf('@') + 1);
648	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
649	            throw new InvalidRequestException(List.of("email"));
650	        }
651	        return lowerCased;
652	    }
653	
654	    /**
655	     * Validate an optional owner postcode. A blank/absent value is treated as "not provided" and
656	     * passes (postcode is optional). When present it must be exactly four digits, and when the owner's
657	     * city has a known region (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) the postcode must fall within
658	     * that region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known
659	     * region accepts any 4-digit postcode. A violation throws an {@link InvalidRequestException} (mapped
660	     * to 400 Bad Request).
661	     *
662	     * @param city     the owner's city (used to resolve the region)
663	     * @param postcode the raw postcode from the request payload, may be {@code null}
664	     */
665	    private void validatePostcode(String city, String postcode) {
666	        if (!StringUtils.hasText(postcode)) {
667	            return;
668	        }
669	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
670	            throw new InvalidRequestException(List.of("postcode"));
671	        }
672	        String region = CITY_REGION.get(city);
673	        int[] range = region == null ? null : REGION_POSTCODE_RANGE.get(region);
674	        if (range != null) {
675	            int value = Integer.parseInt(postcode);
676	            if (value < range[0] || value > range[1]) {
677	                throw new InvalidRequestException(List.of("postcode"));
678	            }
679	        }
680	    }
681	
682	    /**
683	     * Normalize a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value that
684	     * already carries a leading '+' keeps its country code; otherwise the default country code
685	     * ({@code +61}) is assumed and a single leading '0' is dropped from the national digits. The
686	     * result must be a '+' followed by 8 to 15 digits, otherwise an {@link InvalidRequestException}
687	     * is thrown (mapped to 400 Bad Request).
688	     *
689	     * @param telephone the raw telephone from the request payload
690	     * @return the E.164 string (e.g. {@code +61412345678})
691	     */
692	    private String normalizeTelephone(String telephone) {
693	        String cleaned = TELEPHONE_SEPARATORS.matcher(telephone).replaceAll("");
694	        String candidate;
695	        if (cleaned.startsWith("+")) {
696	            candidate = cleaned;
697	        } else {
698	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
699	            candidate = "+" + DEFAULT_COUNTRY_CODE + national;
700	        }
701	        if (!E164_PATTERN.matcher(candidate).matches()) {
702	            throw new InvalidRequestException(List.of("telephone"));
703	        }
704	        // For country codes with a known fixed national-number length, reject a candidate whose
705	        // national digits (everything after the '+' and the country code) do not match that length.
706	        String digits = candidate.substring(1);
707	        for (Map.Entry<String, Integer> entry : COUNTRY_NATIONAL_LENGTH.entrySet()) {
708	            String countryCode = entry.getKey();
709	            if (digits.startsWith(countryCode)) {
710	                int nationalLength = digits.length() - countryCode.length();
711	                if (nationalLength != entry.getValue()) {
712	                    throw new InvalidRequestException(List.of("telephone"));
713	                }
714	                break;
715	            }
716	        }
717	        return candidate;
718	    }
719	
720	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
721	    @Transactional
722	    @Override
723	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
724	        Owner owner = this.clinicService.findOwnerById(ownerId);
725	        if (owner == null) {
726	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
727	        }
728	        this.clinicService.deleteOwner(owner);
729	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
730	    }
731	
732	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
733	    @Override
734	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
735	        Owner owner = this.clinicService.findOwnerById(ownerId);
736	        if (owner == null) {
737	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
738	        }
739	        HttpHeaders headers = new HttpHeaders();
740	        Pet pet = petMapper.toPet(petFieldsDto);
741	        owner.setId(ownerId);
742	        pet.setOwner(owner);
743	        pet.getType().setName(null);
744	        this.clinicService.savePet(pet);
745	        PetDto petDto = petMapper.toPetDto(pet);
746	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
747	            .buildAndExpand(pet.getId()).toUri());
748	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
749	    }
750	
751	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
752	    @Override
753	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
754	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
755	        if (currentOwner != null) {
756	            Pet currentPet = this.clinicService.findPetById(petId);
757	            if (currentPet != null) {
758	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
759	                currentPet.setName(petFieldsDto.getName());
760	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
761	                this.clinicService.savePet(currentPet);
762	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
763	            }
764	        }
765	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
766	    }
767	
768	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
769	    @Override
770	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
771	        HttpHeaders headers = new HttpHeaders();
772	        Visit visit = visitMapper.toVisit(visitFieldsDto);
773	        Pet pet = new Pet();
774	        pet.setId(petId);
775	        visit.setPet(pet);
776	        this.clinicService.saveVisit(visit);
777	        VisitDto visitDto = visitMapper.toVisitDto(visit);
778	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
779	            .buildAndExpand(visit.getId()).toUri());
780	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
781	    }
782	
783	
784	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
785	    @Override
786	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
787	        Owner owner = this.clinicService.findOwnerById(ownerId);
788	        if (owner != null) {
789	            Pet pet = owner.getPet(petId);
790	            if (pet != null) {
791	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
792	            }
793	        }
794	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
795	    }
796	}
