167	        if (value == null) {
168	            return 0;
169	        }
170	        int sum = 0;
171	        boolean doubleDigit = true;
172	        for (int i = value.length() - 1; i >= 0; i--) {
173	            char c = value.charAt(i);
174	            if (c < '0' || c > '9') {
175	                continue;
176	            }
177	            int digit = c - '0';
178	            if (doubleDigit) {
179	                digit *= 2;
180	                if (digit > 9) {
181	                    digit -= 9;
182	                }
183	            }
184	            sum += digit;
185	            doubleDigit = !doubleDigit;
186	        }
187	        return (10 - (sum % 10)) % 10;
188	    }
