213	                break;
214	            }
215	        }
216	        if (countryCode == null) {
217	            return telephone;
218	        }
219	        String national = digits.substring(countryCode.length());
220	        StringBuilder grouped = new StringBuilder();
221	        for (int i = 0; i < national.length(); i++) {
222	            if (i > 0 && i % 3 == 0) {
